"""สร้าง db/103_quiz_fast500.sql — คำถามเน้นตอบเร็วและจำ 500 ข้อ สำหรับการต่อสู้/ควิซ (quiz_questions, ทุกห้อง)
คำตอบคำนวณจากตารางข้อมูลในสคริปต์ (มวลโมเลกุล การจัดอิเล็กตรอน สูตรไอออนิก ฯลฯ) เพื่อไม่ให้พิมพ์ผิด"""
import os, re, random, collections, math
SUB = str.maketrans("0123456789+-", "₀₁₂₃₄₅₆₇₈₉₊₋"); SUP = str.maketrans("0123456789+-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻")
def U(s):
    s = re.sub(r"\^([0-9]*[+-])", lambda m: m.group(1).translate(SUP), s)
    return re.sub(r"(?<=[A-Za-z\)])(\d+)", lambda m: m.group(1).translate(SUB), s)
def seed(s):
    h = 17
    for c in s: h = (h * 137 + ord(c)) % 1000003
    return h
Q = []
def H(topic, q, ok, wrong, ex):
    ch = [ok] + list(wrong)
    assert len(ch) == 4 and len(set(ch)) == 4, (q, ch)
    order = list(range(4)); random.Random(seed(q)).shuffle(order)
    Q.append((topic, q, [ch[i] for i in order], order.index(0), ex))
def pick(pool, ok, n, key):
    r = random.Random(seed(key)); c = [x for x in dict.fromkeys(pool) if x != ok]; r.shuffle(c); return c[:n]
def num(x):
    return str(int(x)) if abs(x - round(x)) < 1e-9 else ("%g" % x)

