# ===== 4) การจัดอิเล็กตรอน =====
def cfg(z):
    if z <= 2: return [z]
    if z <= 10: return [2, z - 2]
    if z <= 18: return [2, 8, z - 10]
    return [2, 8, 8, z - 18]
def cs(c): return ",".join(map(str, c))
for s, n, z in EL[2:20]:
    c = cfg(z); ok = cs(c)
    cand = []
    if len(c) >= 2: cand.append(cs(c[:-2] + [c[-2] - 1, c[-1] + 1]))
    cand += [cs(cfg(z - 1)), cs(cfg(z + 1)), cs([z])]
    cand = [x for x in dict.fromkeys(cand) if x != ok]
    H("การจัดอิเล็กตรอน", f"{s} (เลขอะตอม {z}) จัดอิเล็กตรอนเป็น", ok, cand[:3], f"{s}: {ok}")
for s, n, z in random.Random(14).sample(EL[:20], 14):
    v = cfg(z)[-1]
