AM = {"H":1,"C":12,"N":14,"O":16,"Na":23,"Mg":24,"Al":27,"P":31,"S":32,"Cl":35.5,"K":39,"Ca":40,"Mn":55,"Fe":56,"Cu":64,"Zn":65,"Ag":108,"Ba":137}
def mr(f):
    def parse(s, i=0):
        tot = 0
        while i < len(s):
            ch = s[i]
            if ch == "(":
                sub, i = parse(s, i + 1)
                m = re.match(r"\d+", s[i:]); k = 1
                if m: k = int(m.group()); i += len(m.group())
                tot += sub * k
            elif ch == ")":
                return tot, i + 1
            else:
                m = re.match(r"[A-Z][a-z]?", s[i:]); el = m.group(); i += len(el)
                m2 = re.match(r"\d+", s[i:]); k = 1
                if m2: k = int(m2.group()); i += len(m2.group())
                tot += AM[el] * k
        return tot, i
    return parse(f)[0]
