# ===== ตัดให้เหลือ 500 =====
here = os.path.dirname(os.path.abspath(__file__)); db = os.path.join(here, "..", "db")
exist = ""
for f in os.listdir(db):
    if f.endswith(".sql") and f not in ("setup_all.sql", "103_quiz_fast500.sql"): exist += open(os.path.join(db, f), encoding="utf-8").read()
before = len(Q)
Q[:] = [x for x in Q if x[1] not in exist]
seen = set(); uniq = []
for x in Q:
    if x[1] in seen: continue
    seen.add(x[1]); uniq.append(x)
Q[:] = uniq
print("ก่อนตัด", before, "หลังตัดซ้ำ", len(Q))
TARGET = int(os.environ.get("N", 500))
rt = random.Random(99)
while len(Q) > TARGET:
    cnt = collections.Counter(t for t, *_ in Q)
    big = cnt.most_common(1)[0][0]
    idx = [i for i, x in enumerate(Q) if x[0] == big]
    Q.pop(rt.choice(idx))
print("total", len(Q), dict(collections.Counter(t for t, *_ in Q)))
if len(Q) == TARGET:
    out = ["-- 103: คำถามเน้นตอบเร็วและจำ " + str(len(Q)) + " ข้อ สำหรับการต่อสู้/ควิซประจำวัน (v2.49) · รันซ้ำได้ (หัวข้อ + โจทย์ซ้ำจะไม่ถูกเพิ่ม)",
           "--  · ทุกห้อง (class_id ว่าง) · เปิดใช้งานอัตโนมัติ · ปิดรายข้อได้ในแท็บ 🎮 มินิเกม",
           "--  · หัวข้อ: " + " · ".join(f"{t} {n}" for t, n in collections.Counter(t for t, *_ in Q).items()), ""]
    for t, q, ch, a, ex in Q:
        out.append("insert into quiz_questions (topic, question, a, b, c, d, answer, explain)\nselect $t$%s$t$, $t$%s$t$, $t$%s$t$, $t$%s$t$, $t$%s$t$, $t$%s$t$, %d, $t$%s$t$\nwhere not exists (select 1 from quiz_questions where topic = $t$%s$t$ and question = $t$%s$t$);" % (t, q, ch[0], ch[1], ch[2], ch[3], a, ex, t, q))
    open(os.path.join(db, "103_quiz_fast500.sql"), "w", encoding="utf-8").write("\n".join(out) + "\n"); print("written")
else:
    print("ยังไม่ครบ", len(Q), "ต้องเพิ่มอีก", TARGET - len(Q))
